import assert from 'node:assert/strict'
import test from 'node:test'
import { buildHumanoidStyleDna, type HumanoidLandmarks } from './final-build-workflow'
import { reviewMarkers, readConfirmedStyleDna } from './marker-review'
const landmarks: HumanoidLandmarks = {
  HeadTop: { x: 100, y: 20 },
  Chin: { x: 100, y: 100 },
  HeadLeft: { x: 60, y: 55 },
  HeadRight: { x: 140, y: 55 },
  EyeLeft: { x: 82, y: 58 },
  EyeRight: { x: 118, y: 58 },
  ShoulderLeft: { x: 65, y: 125 },
  ShoulderRight: { x: 135, y: 125 },
  WaistLeft: { x: 72, y: 175 },
  WaistRight: { x: 128, y: 175 },
  FeetBottom: { x: 100, y: 300 },
}
const imageSize = { width: 200, height: 320 }
test('lists missing markers instead of treating partial placement as complete', () => {
  const review = reviewMarkers({ HeadTop: landmarks.HeadTop }, imageSize)
  assert.equal(review.placed, 1)
  assert.equal(review.valid, false)
  assert.ok(review.missing.includes('FeetBottom'))
})
test('rejects nonfinite, out-of-bounds, reversed and degenerate markers', () => {
  for (const changed of [
    { HeadTop: { x: NaN, y: 20 } },
    { FeetBottom: { x: 100, y: 321 } },
    { EyeLeft: landmarks.EyeRight, EyeRight: landmarks.EyeLeft },
    { Chin: landmarks.HeadTop },
    { FeetBottom: { x: 100, y: 10 } },
  ]) assert.equal(reviewMarkers({ ...landmarks, ...changed }, imageSize).valid, false)
})
test('confirmed StyleDNA remains usable without an editor DOM', () => {
  const styleDna = buildHumanoidStyleDna({ source: 'front.png', imageSize, landmarks })
  const stored = JSON.stringify({ schemaVersion: 'marker-review/v1', confirmedAt: '2026-10-22T00:00:00Z', styleDna })
  assert.deepEqual(readConfirmedStyleDna(stored), styleDna)
  assert.equal(reviewMarkers(landmarks, imageSize).valid, true)
})
test('generation rejects missing, unconfirmed or invalid saved review', () => {
  assert.throws(() => readConfirmedStyleDna(null), /confirm markers/)
  assert.throws(() => readConfirmedStyleDna('{}'), /confirm markers/)
  assert.throws(() => readConfirmedStyleDna(JSON.stringify({ schemaVersion: 'marker-review/v1', confirmedAt: 'now', styleDna: { source: 'front.png', imageSize, landmarks: {} } })), /missing markers/)
})

import { HUMANOID_LANDMARK_KEYS, buildHumanoidStyleDna, type HumanoidLandmarkKey, type Point } from './final-build-workflow'

export const MARKER_REVIEW_KEY = 'low-poly-character-studio.marker-review.v1'

export function reviewMarkers(landmarks: Partial<Record<HumanoidLandmarkKey, Point>>, imageSize: { width: number; height: number }) {
  const missing = HUMANOID_LANDMARK_KEYS.filter((key) => !landmarks[key])
  const invalid = HUMANOID_LANDMARK_KEYS.filter((key) => {
    const point = landmarks[key]
    return point && (!Number.isFinite(point.x) || !Number.isFinite(point.y) || point.x < 0 || point.y < 0 || point.x > imageSize.width || point.y > imageSize.height)
  })
  let error = missing.length ? `Place missing markers: ${missing.join(', ')}.` : invalid.length ? `Move markers inside the image: ${invalid.join(', ')}.` : ''
  if (!error) {
    try {
      if (!(imageSize.width > 0 && imageSize.height > 0)) throw new Error('Load a reference image first.')
      buildHumanoidStyleDna({ source: 'marker-review', imageSize, landmarks })
      if (landmarks.HeadTop!.y >= landmarks.Chin!.y || landmarks.Chin!.y >= landmarks.FeetBottom!.y) throw new Error('Head top, chin, and feet must run from top to bottom.')
      for (const [left, right] of [['HeadLeft', 'HeadRight'], ['EyeLeft', 'EyeRight'], ['ShoulderLeft', 'ShoulderRight'], ['WaistLeft', 'WaistRight']] as const) {
        if (landmarks[left]!.x >= landmarks[right]!.x) throw new Error(`${left} must be to the image-left of ${right}.`)
      }
    } catch (cause) { error = cause instanceof Error ? cause.message : 'Check marker positions.' }
  }
  return { missing, invalid, placed: HUMANOID_LANDMARK_KEYS.length - missing.length, total: HUMANOID_LANDMARK_KEYS.length, valid: !error, error }
}

export function readConfirmedStyleDna(value: string | null) {
  if (!value) throw new Error('Review and confirm markers before generation.')
  const review = JSON.parse(value)
  if (review.schemaVersion !== 'marker-review/v1' || !review.confirmedAt || !review.styleDna) throw new Error('Review and confirm markers before generation.')
  const { source, imageSize, landmarks } = review.styleDna
  const result = reviewMarkers(landmarks, imageSize)
  if (!result.valid) throw new Error(result.error)
  return buildHumanoidStyleDna({ source, imageSize, landmarks })
}

/* Product-owner simplification pass.
   Marketing content scrolls naturally; the creative Studio keeps one task in focus. */

/* The landing experience is the actual scroll container. Without a constrained
   height, lower marketing sections can extend beyond the root and appear clipped. */
.landingExperience {
  width: 100%;
  height: 100dvh;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  scroll-behavior: smooth;
  overscroll-behavior-y: contain;
}

.landingPipeline {
  scroll-margin-top: 72px;
}

/* Remove the duplicate current-step treatment from the global Studio chrome.
   The top bar is project identity + actions; the workspace heading owns step context. */
.guidedStudioTopbar {
  grid-template-columns: minmax(0, 1fr) auto;
}

.guidedStudioTopbarActions button,
.guidedDrawerClose {
  min-height: 34px;
  padding: 7px 10px;
  border: 1px solid #3a425c;
  border-radius: 8px;
  background: #24293a;
  color: #f4f6fb;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
}

.guidedStudioTopbarActions button:hover,
.guidedStudioTopbarActions button:focus-visible,
.guidedDrawerClose:hover,
.guidedDrawerClose:focus-visible {
  border-color: #7180aa;
  background: #2d3448;
}

.guidedWorkspaceHeading .guidedEyebrow {
  display: block;
  margin-bottom: 2px;
}

/* Review/confirmation is a blocker only when the user reaches that step. It is
   no longer a persistent dashboard above reference and marker work. */
.verticalSliceReadiness {
  padding: 10px 14px;
  gap: 8px;
}

.verticalSliceReadinessHeading {
  gap: 12px;
}

.verticalSliceReadinessHeading small {
  margin-top: 2px;
}

.verticalSliceReadinessRow {
  gap: 12px;
}

.verticalSliceReadinessRow .primary {
  min-width: 220px;
}

/* Large laptops use workflow/guidance as drawers. The permanent left column is
   reserved for the active task's controls so the canvas gets the working area. */
@media (max-width: 1399.98px) {
  .guidedStudioBody {
    display: block;
  }

  .guidedStepRail {
    position: fixed;
    z-index: 80;
    top: 58px;
    left: 0;
    bottom: 0;
    width: min(320px, 92vw);
    transform: translateX(-100%);
    transition: transform 0.18s ease;
    box-shadow: 16px 0 40px rgba(0, 0, 0, 0.45);
  }

  .guidedStepRail.isOpen {
    transform: translateX(0);
  }

  .guidedStudioTopbarActions .guidedMobileControl,
  .guidedStepRail .guidedDrawerClose {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .guidedMainWorkspace {
    width: 100%;
    height: calc(100dvh - 58px);
  }

  /* Marker placement already has the same view controls in the canvas toolbar.
     Keep the left task rail focused on landmarks instead of duplicating buttons. */
  .guidedStudioStep--2 .referenceWorkspace .sidebar .controls,
  .guidedStudioStep--2 .referenceWorkspace .sidebar > h2:first-child {
    display: none;
  }

  .guidedStudioStep--2 .referenceWorkspace .sidebar > .hint {
    margin-top: 0;
  }
}

/* On the laptop marker workspace the collapsed reference control belongs to the
   task rail. It must not float across the current-landmark header and canvas. */
@media (min-width: 992px) and (max-width: 1399.98px) {
  .guidedStudioStep--2 .referenceWorkspace .referenceManager.collapsed {
    top: 10px;
    left: 10px;
    width: min(230px, calc(100% - 20px));
    padding: 8px 10px;
  }

  .guidedStudioStep--2 .referenceWorkspace .referenceManager.collapsed .referenceManagerHeading {
    gap: 6px;
  }

  .guidedStudioStep--2 .referenceWorkspace .referenceManager.collapsed .referenceManagerHeading h2 {
    font-size: 12px;
    letter-spacing: 0.08em;
  }

  .guidedStudioStep--2 .referenceWorkspace .referenceManager.collapsed .referenceManagerHeadingActions button {
    padding: 7px 8px;
    font-size: 12px;
    white-space: nowrap;
  }

  .guidedStudioStep--2 .referenceWorkspace .sidebar {
    padding-top: 66px;
  }
}

/* Short laptop browser viewports need compact marketing sections, but they still
   scroll naturally instead of trying to squeeze the whole explanation on screen. */
@media (max-height: 760px) and (min-width: 992px) {
  .landingPipeline {
    padding: 34px 0 26px;
    scroll-margin-top: 60px;
  }

  .landingPipeline h2 {
    max-width: 680px;
    margin: 7px 0 20px;
    font-size: clamp(30px, 3vw, 40px);
  }

  .landingPipeline ol {
    gap: 8px;
  }

  .landingPipeline li {
    min-height: 92px;
    padding: 14px;
  }

  .landingTiles {
    gap: 14px;
    padding-bottom: 48px;
  }

  .landingTiles article {
    min-height: 0;
    padding: 20px;
  }

  .landingTiles h2 {
    margin: 18px 0 8px;
    font-size: 21px;
  }

  .guidedStepRail,
  .guidedInspector {
    top: 52px;
  }

  .guidedMainWorkspace {
    height: calc(100dvh - 52px);
  }
}

@media (max-width: 680px) {
  .landingPipeline {
    scroll-margin-top: 68px;
  }

  .guidedStudioTopbarActions {
    gap: 5px;
  }

  .guidedStudioTopbarActions button {
    padding: 7px 8px;
    font-size: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .landingExperience {
    scroll-behavior: auto;
  }

  .guidedStepRail {
    transition: none;
  }
}

/* Reference controls participate in layout instead of covering marker tools. */
.studioApplicationShell .referenceManager.collapsed {
  position: relative;
  inset: auto;
  width: auto;
  flex: 0 0 auto;
  margin: 8px;
  box-shadow: none;
}
.studioApplicationShell .guidedMainWorkspace { overflow-y: auto; }
.studioApplicationShell .workspace { overflow-y: auto; }
.markerReview { flex: 0 0 auto; padding: 8px; border: 1px solid #46506c; border-radius: 8px; margin-bottom: 8px; }
.markerReview p { font-size: 13px; overflow-wrap: anywhere; }
.markerReview > div { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 6px; }
.markerReview button { padding: 8px 10px; background: #24293a; color: #fff; border: 1px solid #7180aa; border-radius: 7px; cursor: pointer; }
.markerReview button:disabled { opacity: .5; cursor: not-allowed; }
.studioApplicationShell .referenceWorkspace .sidebar { padding-top: 12px; }

